-- Disposable test Supabase only; requires 001–006 and pgTAP. Never run fixtures on the main project.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select is((select count(*)::integer from pg_class where oid in ('public.book_polls'::regclass,
 'public.book_poll_options'::regclass,'public.book_votes'::regclass) and relrowsecurity),3,'all voting tables have RLS');
select ok(has_schema_privilege('authenticated','private','USAGE'),'invoker wrapper can resolve private implementation');
select ok(has_function_privilege('authenticated','private.cast_book_vote(uuid,uuid)','EXECUTE'),'authenticated can execute validated implementation');
select ok(not has_function_privilege('authenticated','private.lock_poll(uuid,boolean)','EXECUTE'),'raw lock helper closed');
select ok(not has_function_privilege('anon','public.cast_book_vote(uuid,uuid)','EXECUTE'),'guest write wrapper closed');
select ok(not has_function_privilege('anon','private.cast_book_vote(uuid,uuid)','EXECUTE'),'guest implementation closed');
select ok(has_function_privilege('anon','public.get_club_book_flags(uuid)','EXECUTE'),'guest can load safe shelf annotations');
select is((select count(*)::integer from pg_proc p join pg_namespace n on n.oid=p.pronamespace
 where n.nspname='public' and p.prosecdef and p.proname in
 ('create_book_poll','cast_book_vote','finalize_book_poll','cancel_book_poll','get_book_poll','list_book_polls','get_club_book_flags')),0,'public RPCs are invoker');
insert into auth.users(id,email,raw_user_meta_data) values
 ('40000000-0000-4000-8000-000000000001','poll-owner@example.test','{"name":"Owner"}'),
 ('40000000-0000-4000-8000-000000000002','poll-member@example.test','{"name":"Member"}'),
 ('40000000-0000-4000-8000-000000000003','poll-admin@example.test','{"name":"Admin"}');
update public.user_access set role='admin' where user_id='40000000-0000-4000-8000-000000000003';
create temp table poll_ctx(label text primary key,id uuid);
grant all on poll_ctx to authenticated,anon;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
insert into poll_ctx select 'club',(public.create_club('{"name":"Poll club","genre":"Проза","description":"Читаємо разом і голосуємо за книги.","format":"online","language":"Українська","meetings_per_month":2}')).id;
insert into poll_ctx select 'one',(public.save_club_book((select id from poll_ctx where label='club'),'{"title":"One","author":"Author"}')).id;
insert into poll_ctx select 'two',(public.save_club_book((select id from poll_ctx where label='club'),'{"title":"Two","author":"Author"}')).id;
insert into poll_ctx select 'three',(public.save_club_book((select id from poll_ctx where label='club'),'{"title":"Three","author":"Author"}')).id;
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Poll',clock_timestamp()+interval '1 hour',array[(select id from poll_ctx where label='one')])$$,'22023',null,'two choices required');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Poll',clock_timestamp()+interval '1 hour',array[(select id from poll_ctx where label='one'),(select id from poll_ctx where label='one')])$$,'22023',null,'duplicate choices rejected');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Poll',clock_timestamp()-interval '1 second',array(select id from poll_ctx where label in ('one','two')))$$,'22023',null,'past deadline rejected');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Poll',clock_timestamp()+interval '1 hour',array[(select id from poll_ctx where label='one'),'40000000-0000-4000-8000-000000000099'::uuid])$$,'22023',null,'foreign or missing book rejected');
insert into poll_ctx select 'poll',(public.create_book_poll((select id from poll_ctx where label='club'),'Choose next',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','two','three') order by label))).id;
insert into poll_ctx select 'a',id from public.book_poll_options where book_id=(select id from poll_ctx where label='one');
insert into poll_ctx select 'b',id from public.book_poll_options where book_id=(select id from poll_ctx where label='two');
insert into poll_ctx select 'z',id from public.book_poll_options where book_id=(select id from poll_ctx where label='three');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Another',clock_timestamp()+interval '2 hours',array(select id from poll_ctx where label in ('one','two')))$$,'23505',null,'one unresolved poll enforced');
select throws_ok($$select public.save_club_book((select id from poll_ctx where label='club'),'{"title":"Changed","author":"Author"}',(select id from poll_ctx where label='one'))$$,'55000',null,'unresolved option metadata locked');
select throws_ok($$select public.start_club_book((select id from poll_ctx where label='one'))$$,'55000',null,'unresolved option cannot start');
select throws_ok($$update public.book_polls set winner_option_id=(select id from poll_ctx where label='a')$$,'42501',null,'no direct result writes');
select throws_ok($$delete from public.book_poll_options$$,'42501',null,'options immutable to client');
select throws_ok($$insert into public.book_votes(poll_id,user_id,option_id) values((select id from poll_ctx where label='poll'),'40000000-0000-4000-8000-000000000002',(select id from poll_ctx where label='a'))$$,'42501',null,'cannot forge vote author');
select lives_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='a'))$$,'owner votes as member');
select throws_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),'40000000-0000-4000-8000-000000000099')$$,'22023',null,'cannot substitute option');
select throws_ok($$select public.finalize_book_poll((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='a'))$$,'55000',null,'no early finalization');
reset role;
insert into public.club_members(club_id,user_id) select id,'40000000-0000-4000-8000-000000000002'::uuid from poll_ctx where label='club';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select lives_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='a'))$$,'member votes');
select lives_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='b'))$$,'member changes same vote');
select is((select count(*)::integer from public.book_votes),1,'voter sees only own row');
select is((public.get_book_poll((select id from poll_ctx where label='poll'))->>'total_votes')::integer,2,'aggregate includes owner vote without identities');
select ok(not exists(select 1 from jsonb_array_elements(public.get_book_poll((select id from poll_ctx where label='poll'))->'options') o where o ? 'user_id' or o ? 'voters'),'results have no voter identity');
select public.remove_club_member((select id from poll_ctx where label='club'),'40000000-0000-4000-8000-000000000002');
select throws_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='a'))$$,'42501',null,'former member cannot change vote');
reset role;
select is((select count(*)::integer from public.book_votes where poll_id=(select id from poll_ctx where label='poll')),2,'leaving retains votes');
insert into public.club_members(club_id,user_id) select id,'40000000-0000-4000-8000-000000000002'::uuid from poll_ctx where label='club';
set local role authenticated;
select lives_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='b'))$$,'rejoined member updates existing vote');
select is((select count(*)::integer from public.book_votes),1,'rejoining grants no additional vote');
select throws_ok($$select public.cancel_book_poll((select id from poll_ctx where label='poll'))$$,'42501',null,'member cannot cancel');
select throws_ok($$select public.finalize_book_poll((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='a'))$$,'42501',null,'member cannot choose winner');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Forged owner',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','two')))$$,'42501',null,'member cannot create poll in another owner club');
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000003","role":"authenticated"}',true);
select lives_ok($$select public.get_book_poll((select id from poll_ctx where label='poll'))$$,'admin may moderate by reading results');
select throws_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='a'))$$,'42501',null,'admin without membership cannot vote');
select throws_ok($$select public.cancel_book_poll((select id from poll_ctx where label='poll'))$$,'42501',null,'admin is not poll owner');
reset role;
update public.user_access set role='user' where user_id='40000000-0000-4000-8000-000000000003';
set local role authenticated;
select is((select count(*)::integer from public.book_polls),0,'outsider cannot read polls through table');
select throws_ok($$select public.get_book_poll((select id from poll_ctx where label='poll'))$$,'42501',null,'outsider RPC denied');
set local role anon;
select throws_ok($$select * from public.book_votes$$,'42501',null,'guest cannot inspect votes table');
select throws_ok($$select public.get_book_poll((select id from poll_ctx where label='poll'))$$,'42501',null,'guest results RPC denied');
select lives_ok($$select public.get_club_book_flags((select id from poll_ctx where label='club'))$$,'public shelf annotations accessible');
reset role;
-- Trusted test-only clock fixtures: no sleeps, no changes to server clock.
update public.book_polls set created_at=clock_timestamp()-interval '2 hours',ends_at=clock_timestamp()-interval '1 hour' where id=(select id from poll_ctx where label='poll');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"40000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select throws_ok($$select public.cast_book_vote((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='b'))$$,'55000',null,'late vote rejected');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Another',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','two')))$$,'23505',null,'expired unresolved still blocks new poll');
select throws_ok($$select public.start_club_book((select id from poll_ctx where label='one'))$$,'55000',null,'expired unresolved still locks books');
select throws_ok($$select public.finalize_book_poll((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='z'))$$,'22023',null,'cannot pick nonleader');
select lives_ok($$select public.finalize_book_poll((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='a'))$$,'tie allows one of leaders');
select is((select status from public.club_books where id=(select id from poll_ctx where label='one')),'planned','winner remains planned');
select ok((select is_next_selected from public.get_club_book_flags((select id from poll_ctx where label='club')) where book_id=(select id from poll_ctx where label='one')),'winner gets next selected label');
select throws_ok($$select public.finalize_book_poll((select id from poll_ctx where label='poll'),(select id from poll_ctx where label='b'))$$,'55000',null,'finalization cannot repeat');
select public.start_club_book((select id from poll_ctx where label='one'));
select public.start_club_book((select id from poll_ctx where label='two'),(select id from poll_ctx where label='one'),'planned');
select ok(not (select is_next_selected from public.get_club_book_flags((select id from poll_ctx where label='club')) where book_id=(select id from poll_ctx where label='one')),'returning winner to planned never resurrects label');
select public.save_club_book((select id from poll_ctx where label='club'),'{"title":"Renamed","author":"Author"}',(select id from poll_ctx where label='one'));
select is((select title_snapshot from public.book_poll_options where id=(select id from poll_ctx where label='a')),'One','history preserves title snapshot');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Not planned',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','two')))$$,'22023',null,'current book cannot be poll option');
insert into poll_ctx select 'sole',(public.create_book_poll((select id from poll_ctx where label='club'),'Sole leader',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','three')))).id;
select public.cast_book_vote((select id from poll_ctx where label='sole'),(select id from public.book_poll_options where poll_id=(select id from poll_ctx where label='sole') and book_id=(select id from poll_ctx where label='one')));
select throws_ok($$select public.cast_book_vote((select id from poll_ctx where label='sole'),(select id from poll_ctx where label='a'))$$,'22023',null,'option from old poll cannot be substituted');
reset role;
update public.book_polls set created_at=clock_timestamp()-interval '2 hours',ends_at=clock_timestamp()-interval '1 hour' where id=(select id from poll_ctx where label='sole');
set local role authenticated;
select throws_ok($$select public.finalize_book_poll((select id from poll_ctx where label='sole'),(select id from public.book_poll_options where poll_id=(select id from poll_ctx where label='sole') and book_id=(select id from poll_ctx where label='three')))$$,'22023',null,'sole leader cannot be overridden');
select lives_ok($$select public.finalize_book_poll((select id from poll_ctx where label='sole'),(select id from public.book_poll_options where poll_id=(select id from poll_ctx where label='sole') and book_id=(select id from poll_ctx where label='one')))$$,'sole leader finalizes');
insert into poll_ctx select 'zero',(public.create_book_poll((select id from poll_ctx where label='club'),'Zero votes',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','three')))).id;
reset role;
update public.book_polls set created_at=clock_timestamp()-interval '2 hours',ends_at=clock_timestamp()-interval '1 hour' where id=(select id from poll_ctx where label='zero');
set local role authenticated;
select lives_ok($$select public.finalize_book_poll((select id from poll_ctx where label='zero'),(select id from public.book_poll_options where poll_id=(select id from poll_ctx where label='zero') limit 1))$$,'zero votes permits any option');
insert into poll_ctx select 'cancel',(public.create_book_poll((select id from poll_ctx where label='club'),'Cancel test',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','three')))).id;
select public.cancel_book_poll((select id from poll_ctx where label='cancel'));
select is((public.get_book_poll((select id from poll_ctx where label='cancel'))->>'status'),'cancelled','cancellation retained in history');
select throws_ok($$select public.cast_book_vote((select id from poll_ctx where label='cancel'),(select id from public.book_poll_options where poll_id=(select id from poll_ctx where label='cancel') limit 1))$$,'55000',null,'cancelled poll rejects votes');
insert into poll_ctx select 'archive',(public.create_book_poll((select id from poll_ctx where label='club'),'Archive test',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','three')))).id;
select public.archive_club((select id from poll_ctx where label='club'));
select is((public.get_book_poll((select id from poll_ctx where label='archive'))->>'cancel_reason'),'club_archived','archive atomically cancels unresolved poll');
select throws_ok($$select public.cast_book_vote((select id from poll_ctx where label='archive'),(select id from public.book_poll_options where poll_id=(select id from poll_ctx where label='archive') limit 1))$$,'55000',null,'archive prevents voting');
select throws_ok($$select public.create_book_poll((select id from poll_ctx where label='club'),'Forbidden',clock_timestamp()+interval '1 hour',array(select id from poll_ctx where label in ('one','three')))$$,'55000',null,'archive prevents new polls');
select is((select count(*)::integer from public.list_book_polls((select id from poll_ctx where label='club'))),5,'owner retains entire archive history');
reset role;
update public.user_access set is_blocked=true where user_id='40000000-0000-4000-8000-000000000001';
set local role authenticated;
select throws_ok($$select public.get_book_poll((select id from poll_ctx where label='poll'))$$,'42501',null,'blocked owner cannot read private results');
select throws_ok($$select public.cancel_book_poll((select id from poll_ctx where label='archive'))$$,'42501',null,'blocked owner cannot invoke mutations');
reset role;
select * from finish();
rollback;
